def get_bio_panel_text(code, username: str) -> tuple:
    title, subtitle, instruction, after = _BIO_PANEL.get(code or DEFAULT_LANGUAGE, _BIO_PANEL[DEFAULT_LANGUAGE])
    return title.replace("{username}", username), subtitle, instruction, after

