def get_wizard_text(code) -> dict:
    row = _WIZARD.get(code or DEFAULT_LANGUAGE, _WIZARD[DEFAULT_LANGUAGE])
    text = dict(zip(_WIZARD_KEYS, row))
    text["footer_ready"] = text["footer_ready"].replace("{button}", text["btn_finish"])
    return text

