def get_notice_titles(code) -> dict:
    error, success, warning = _NOTICE_TITLES.get(code or DEFAULT_LANGUAGE, _NOTICE_TITLES[DEFAULT_LANGUAGE])
    return {"error": error, "success": success, "warning": warning}

