def get_text(key: str, code=None, **values) -> str:
    table = _MESSAGES.get(code or DEFAULT_LANGUAGE, _MESSAGES[DEFAULT_LANGUAGE])
    text = table.get(key) or _MESSAGES[DEFAULT_LANGUAGE][key]
    values.setdefault("support", SUPPORT)
    return re.sub(r"\{(\w+)\}", lambda m: str(values.get(m.group(1), m.group(0))), text)

